import * as THREE from 'three';

const mount=document.querySelector('#game'), loading=document.querySelector('#loading');
const scene=new THREE.Scene(); scene.background=new THREE.Color('#f6a17f'); scene.fog=new THREE.FogExp2('#e98d91',.00145);
const camera=new THREE.PerspectiveCamera(54,innerWidth/innerHeight,.1,500); camera.position.set(0,5.4,10.5);
const renderer=new THREE.WebGLRenderer({antialias:true,alpha:false,powerPreference:'high-performance'}); renderer.setPixelRatio(Math.min(devicePixelRatio,1.8)); renderer.setSize(innerWidth,innerHeight); renderer.shadowMap.enabled=true; renderer.shadowMap.type=THREE.PCFSoftShadowMap; renderer.outputColorSpace=THREE.SRGBColorSpace; renderer.toneMapping=THREE.ACESFilmicToneMapping; renderer.toneMappingExposure=1.18; mount.appendChild(renderer.domElement);
scene.add(new THREE.HemisphereLight('#fff0d6','#59678a',2.05)); const sunLight=new THREE.DirectionalLight('#fff1cf',2.2); sunLight.position.set(-25,40,25); sunLight.castShadow=true; sunLight.shadow.mapSize.set(1024,1024); sunLight.shadow.camera.left=-38;sunLight.shadow.camera.right=38;sunLight.shadow.camera.top=42;sunLight.shadow.camera.bottom=-24;scene.add(sunLight);
const mat=(color,roughness=.85,metalness=0,emissive=null)=>new THREE.MeshStandardMaterial({color,roughness,metalness,...(emissive?{emissive:new THREE.Color(emissive),emissiveIntensity:.75}:{})});
const mats={road:mat('#393b52'),asphalt:mat('#47485b'),line:mat('#fff1c8',.5),grass:mat('#7bc28a'),darkGrass:mat('#4b9b80'),hill1:mat('#9bd58b'),hill2:mat('#75bf91'),wood:mat('#9b674d'),white:mat('#fff4de'),black:mat('#25263a'),chrome:mat('#d8e6e5',.25,.75),glass:mat('#35536c',.28,.25),leaf:mat('#52ad7d'),leaf2:mat('#ffbd75'),pink:mat('#ed738d'),yellow:mat('#ffd36e'),red:mat('#e95769'),blue:mat('#5f9be2')};
let worldDistance=0, speed=19, running=false, selectedCar='pickup', contacts=0, score=0, playerX=0, steer=0, dash=0, shake=0, elapsed=0, beat=0, soundOn=true, audio=null;
const roadWidth=13, playerZ=0, objects=[], traffic=[], particles=[];
const player=new THREE.Group(); scene.add(player);
const roadSegments=[]; const segmentCount=48, segLength=5;
function makeBox(parent,w,h,d,material,x,y,z,bevel=0){const g=new THREE.BoxGeometry(w,h,d);const mesh=new THREE.Mesh(g,material);mesh.position.set(x,y,z);mesh.castShadow=true;mesh.receiveShadow=true;parent.add(mesh);return mesh;}
function pathX(s){return Math.sin(s*.0036)*5.8+Math.sin(s*.00115+1.3)*8.5;}
function pathAngle(s){return Math.atan((pathX(s+2)-pathX(s-2))/4);}
// Vast softly layered landscape and sunset disc
const ground=new THREE.Mesh(new THREE.PlaneGeometry(1500,1000),mats.grass);ground.rotation.x=-Math.PI/2;ground.position.set(0,-.52,-300);ground.receiveShadow=true;scene.add(ground);
const skyDome=new THREE.Mesh(new THREE.SphereGeometry(440,32,20),new THREE.MeshBasicMaterial({color:'#f39b91',side:THREE.BackSide}));skyDome.position.y=20;scene.add(skyDome);
const sunGroup=new THREE.Group();sunGroup.position.set(-48,37,-245);scene.add(sunGroup);const sun=new THREE.Mesh(new THREE.SphereGeometry(17,32,24),new THREE.MeshBasicMaterial({color:'#ffd48a'}));sunGroup.add(sun);const sunAura=new THREE.Mesh(new THREE.SphereGeometry(21,32,24),new THREE.MeshBasicMaterial({color:'#ffad9a',transparent:true,opacity:.22,side:THREE.BackSide}));sunGroup.add(sunAura);
// distant layered hill ribbons
for(let layer=0;layer<3;layer++){const verts=[],idx=[];for(let i=0;i<=70;i++){const x=-420+i*12;const z=-180-layer*32+Math.sin(i*.47+layer*2)*8;const y=4+Math.sin(i*.29+layer)*7+Math.sin(i*.09+layer*4)*5-layer*1.5;verts.push(x,y,z,x, -2,z);if(i<70){let a=i*2;idx.push(a,a+2,a+1,a+2,a+3,a+1)}}const geo=new THREE.BufferGeometry();geo.setAttribute('position',new THREE.Float32BufferAttribute(verts,3));geo.setIndex(idx);geo.computeVertexNormals();const mesh=new THREE.Mesh(geo,new THREE.MeshStandardMaterial({color:['#8bbd9b','#789fb1','#8c8db2'][layer],roughness:1,side:THREE.DoubleSide}));scene.add(mesh);}
// Road slab and bright shoulders, recycled as individual slices so the curve breathes
for(let i=0;i<segmentCount;i++){const group=new THREE.Group();scene.add(group);const z=-190+i*segLength;makeBox(group,roadWidth,.22,segLength,mats.road,0,-.2,0);makeBox(group,.22,.025,segLength,mats.yellow,-roadWidth/2+.24,-.075,0);makeBox(group,.22,.025,segLength,mats.yellow,roadWidth/2-.24,-.075,0);for(const lane of [-1,1]){const dash=makeBox(group,.14,.026,2.1,mats.line,lane*roadWidth/6,-.063,0);dash.material=mats.white;}roadSegments.push({group,z});}
// Repeating shoulder grass strips
const shoulderGeo=new THREE.BoxGeometry(28,.18,4.7);for(let i=0;i<segmentCount;i++){const m=new THREE.Mesh(shoulderGeo,i%2?mats.grass:mats.darkGrass);m.position.y=-.39;scene.add(m);objects.push({kind:'shoulder',mesh:m,z:-190+i*5});}
function addProp(type,x,z,scale=1){let g=new THREE.Group();scene.add(g);let entry={kind:type,group:g,z,side:x>0?1:-1,offset:Math.abs(x),phase:Math.random()*6.28,scale};objects.push(entry);buildProp(entry);return entry;}
function buildProp(e){const g=e.group;while(g.children.length){const c=g.children.pop();c.geometry?.dispose();}g.scale.setScalar(e.scale);
 if(e.kind==='tree'){const trunk=new THREE.Mesh(new THREE.CylinderGeometry(.18,.28,2.2,6),mats.wood);trunk.position.y=.6;trunk.castShadow=true;g.add(trunk);const colors=[mats.leaf,mats.leaf2,mats.pink];for(let i=0;i<3;i++){const crown=new THREE.Mesh(new THREE.IcosahedronGeometry(1.05-i*.13,1),colors[(Math.floor(e.phase*10)+i)%3]);crown.position.set(Math.sin(i*2)*.28,1.85+i*.48,Math.cos(i*2)*.2);crown.castShadow=true;g.add(crown);}}
 else if(e.kind==='barn'){makeBox(g,3.8,2.5,2.7,mats.red,0,1.25,0);const roof=new THREE.Mesh(new THREE.ConeGeometry(2.9,1.25,4),mats.red);roof.rotation.y=Math.PI/4;roof.scale.set(1,.7,.75);roof.position.y=3;g.add(roof);makeBox(g,.9,1.5,.04,mats.wood,0,.75,1.38);makeBox(g,1.1,.12,.08,mats.white,0,1.5,1.43);}
 else if(e.kind==='lamp'){const pole=new THREE.Mesh(new THREE.CylinderGeometry(.08,.13,5,6),mats.black);pole.position.y=2.5;g.add(pole);const arm=makeBox(g,1.4,.1,.12,mats.black,.65,4.8,0);const bulb=new THREE.Mesh(new THREE.SphereGeometry(.24,10,8),new THREE.MeshBasicMaterial({color:'#ffe5a0'}));bulb.position.set(1.2,4.7,0);g.add(bulb);}
 else if(e.kind==='fence'){for(let j=0;j<4;j++)makeBox(g,.12,1.05,.14,mats.wood,-1.2+j*.8,.5,0);makeBox(g,3,.12,.14,mats.wood,0,.38,0);makeBox(g,3,.12,.14,mats.wood,0,.8,0);}
 else if(e.kind==='flower'){for(let i=0;i<5;i++){const stem=new THREE.Mesh(new THREE.CylinderGeometry(.025,.035,.35,5),mats.leaf);stem.position.set((i-2)*.12,.15,0);g.add(stem);const f=new THREE.Mesh(new THREE.SphereGeometry(.1,7,5),[mats.pink,mats.yellow,mats.white][i%3]);f.position.set((i-2)*.12,.36,0);g.add(f);}}
 else if(e.kind==='neon'){makeBox(g,1.5,5,.25,mats.blue,0,2.5,0);makeBox(g,1.15,3.6,.3,mats.pink,0,3.3,.18);makeBox(g,1.2,.14,.35,mats.white,0,4.8,.4);}
}
for(let i=0;i<85;i++){let z=-240+i*6.4;const side=i%2?1:-1;const r=Math.random();addProp(r<.67?'tree':r<.82?'fence':r<.91?'flower':'barn',side*(10+Math.random()*12),z,.65+Math.random()*.75);}
// Pickup and compact vehicles from clean toy-like geometry
const bodyMats={pickup:mat('#ff774f',.42,.12),compact:mat('#52d2c3',.42,.1)};
function buildCar(type,colorMat,trafficCar=false){const root=new THREE.Group(), body=new THREE.Group();root.add(body);const carW=type==='pickup'?1.92:1.75, carD=type==='pickup'?4.1:3.55;
 makeBox(body,carW,.72,carD,colorMat,0,.67,0);makeBox(body,carW*.92,.17,carD*.34,colorMat,0,1.08,-carD*.27); // hood
 if(type==='pickup'){makeBox(body,carW*.83,.85,1.6,colorMat,0,1.38,-.3);const cabTop=makeBox(body,carW*.79,.12,1.55,colorMat,0,1.87,-.3);makeBox(body,carW*.73,.57,.055,mats.glass,0,1.43,.49);makeBox(body,carW*.73,.55,.055,mats.glass,0,1.42,-1.08);makeBox(body,carW*.75,.08,1.3,mats.black,0,1.9,-.3);makeBox(body,carW*.82,.24,1.05,mat('#bd553e'),0,1.02,1.37);makeBox(body,carW*.65,.09,1.3,mats.black,0,.86,1.4);}
 else{makeBox(body,carW*.85,.75,1.9,colorMat,0,1.3,-.17);makeBox(body,carW*.7,.56,.05,mats.glass,0,1.36,.79);makeBox(body,carW*.68,.5,.05,mats.glass,0,1.35,-1.1);makeBox(body,carW*.88,.12,1.48,mats.black,0,1.7,-.14);}
 makeBox(body,carW*1.04,.18,.16,mats.chrome,0,.45,-carD/2-.06);makeBox(body,carW*1.04,.18,.16,mats.chrome,0,.45,carD/2+.06);
 for(const x of [-carW*.52,carW*.52])for(const z of [-carD*.31,carD*.31]){const wheel=new THREE.Mesh(new THREE.CylinderGeometry(.43,.43,.27,14),mats.black);wheel.rotation.z=Math.PI/2;wheel.position.set(x,.43,z);wheel.castShadow=true;body.add(wheel);const hub=new THREE.Mesh(new THREE.CylinderGeometry(.21,.21,.29,10),mats.chrome);hub.rotation.z=Math.PI/2;hub.position.copy(wheel.position);body.add(hub);const hub2=new THREE.Mesh(new THREE.CylinderGeometry(.08,.08,.3,8),mats.black);hub2.rotation.z=Math.PI/2;hub2.position.copy(wheel.position);body.add(hub2);}
 for(const x of [-.62,.62]){const head=new THREE.Mesh(new THREE.BoxGeometry(.37,.2,.08),new THREE.MeshStandardMaterial({color:'#fff1ad',emissive:'#ffe58a',emissiveIntensity:2}));head.position.set(x,.76,-carD/2-.08);body.add(head);const tail=new THREE.Mesh(new THREE.BoxGeometry(.33,.19,.08),new THREE.MeshStandardMaterial({color:'#ff4f61',emissive:'#ff183a',emissiveIntensity:1.3}));tail.position.set(x,.75,carD/2+.08);body.add(tail);}
 root.userData.body=body;root.userData.type=type;root.userData.width=carW;root.userData.length=carD;return root;}
const playerCar=buildCar('pickup',bodyMats.pickup);player.add(playerCar);player.position.set(0,0,playerZ);player.castShadow=true;
const trafficColors=['#f5c34b','#679be9','#ef7187','#71cc99','#bf8bf0','#f0874f','#e9e9ee'];
function spawnTraffic(z=-120){const type=Math.random()<.48?'pickup':'compact';const t=buildCar(type,mat(trafficColors[Math.floor(Math.random()*trafficColors.length)],.48,.08),true);scene.add(t);const lane=[-4.1,0,4.1][Math.floor(Math.random()*3)];const ob={mesh:t,x:lane,z,speed:Math.random()*5+5,hit:false,knock:0,dx:0,baseLane:lane};traffic.push(ob);return ob;}
for(let i=0;i<9;i++)spawnTraffic(-38-i*19);
loading.classList.add('off');

// Puffy clouds, roadside blooms and a little distant scenery make the horizon feel alive.
const clouds=[];for(let i=0;i<18;i++){const c=new THREE.Group();scene.add(c);for(let j=0;j<5;j++){const puff=new THREE.Mesh(new THREE.SphereGeometry(1,10,8),new THREE.MeshBasicMaterial({color:j%2?'#fff0dd':'#ffe6d9'}));puff.scale.set(1.7+Math.random(),.55+Math.random()*.35,.7);puff.position.set(j*1.35-2.7,Math.sin(j)*.25,Math.random()*.7);c.add(puff);}c.position.set((Math.random()-.5)*190,21+Math.random()*22,-90-Math.random()*210);c.scale.setScalar(.7+Math.random()*.8);clouds.push(c);}
// Soft stylized glow beyond the road, plus a subtle road-side ambience.
const glowLight=new THREE.PointLight('#ff9c9b',32,180,2);glowLight.position.set(-25,13,-70);scene.add(glowLight);
const hud=document.querySelector('#hud'),menu=document.querySelector('#menu'),gameOver=document.querySelector('#gameOver');
const scoreNode=document.querySelector('#score'),speedNode=document.querySelector('#speed'),countNode=document.querySelector('#contactCount'),distNode=document.querySelector('#distance');
function startAudio(){if(!soundOn)return;try{audio=audio||new (window.AudioContext||window.webkitAudioContext)();audio.resume();if(audio.started)return;audio.started=true;const master=audio.createGain();master.gain.value=.18;master.connect(audio.destination);const notes=[261.63,329.63,392,329.63,293.66,349.23,440,349.23];let n=0;function note(){if(!audio||audio.state!=='running')return;const now=audio.currentTime;const osc=audio.createOscillator(),gain=audio.createGain();osc.type='sine';osc.frequency.value=notes[n%notes.length];gain.gain.setValueAtTime(.0001,now);gain.gain.exponentialRampToValueAtTime(.16,now+.06);gain.gain.exponentialRampToValueAtTime(.0001,now+.52);osc.connect(gain);gain.connect(master);osc.start(now);osc.stop(now+.55);if(n%4===0){const bass=audio.createOscillator(),bg=audio.createGain();bass.type='triangle';bass.frequency.value=notes[(n+4)%notes.length]/2;bg.gain.setValueAtTime(.08,now);bg.gain.exponentialRampToValueAtTime(.0001,now+.3);bass.connect(bg);bg.connect(master);bass.start(now);bass.stop(now+.32);}n++;}note();audio.timer=setInterval(note,430);}catch(e){console.warn('Audio unavailable',e);}}
function soundEffect(freq=120,duration=.22,type='sawtooth',volume=.16){if(!audio||!soundOn)return;try{const o=audio.createOscillator(),g=audio.createGain(),now=audio.currentTime;o.type=type;o.frequency.setValueAtTime(freq,now);o.frequency.exponentialRampToValueAtTime(Math.max(42,freq*.48),now+duration);g.gain.setValueAtTime(volume,now);g.gain.exponentialRampToValueAtTime(.0001,now+duration);o.connect(g);g.connect(audio.destination);o.start(now);o.stop(now+duration);}catch{}}
function playStart(){startAudio();running=true;contacts=0;score=0;worldDistance=0;speed=19;playerX=0;steer=0;dash=0;shake=0;hud.classList.add('active');menu.classList.add('hidden');gameOver.classList.add('hidden');updateContacts();}
function finish(){running=false;document.querySelector('#finalScore').textContent=Math.floor(score).toLocaleString();document.querySelector('#finalDistance').textContent=`You made it ${(worldDistance/1000).toFixed(1)} km`;gameOver.classList.remove('hidden');}
function updateContacts(){countNode.textContent=contacts;document.querySelectorAll('.contact-dots i').forEach((el,i)=>el.classList.toggle('hit',i<contacts));}
document.querySelector('#startButton').addEventListener('click',playStart);document.querySelector('#retryButton').addEventListener('click',playStart);
document.querySelectorAll('.car-option').forEach(el=>el.addEventListener('click',()=>{document.querySelectorAll('.car-option').forEach(x=>x.classList.remove('selected'));el.classList.add('selected');selectedCar=el.dataset.car;player.remove(playerCar);const next=buildCar(selectedCar,bodyMats[selectedCar]);player.add(next);playerCar.userData.type='unused';}));
document.querySelector('#soundToggle').addEventListener('click',e=>{soundOn=!soundOn;e.currentTarget.innerHTML=soundOn?'♫ &nbsp;SOUND ON':'♫ &nbsp;SOUND OFF';if(soundOn)startAudio();else if(audio){audio.close();audio=null;}});
// Hold-to-steer and double-tap dash; pointer capture makes release reliable on mobile.
let activePointer=null,lastTapTime=0,lastTapSide=0;const canvas=renderer.domElement;
canvas.addEventListener('pointerdown',e=>{if(!running)return;e.preventDefault();canvas.setPointerCapture?.(e.pointerId);activePointer=e.pointerId;const side=e.clientX<innerWidth/2?-1:1;steer=side;const now=performance.now();if(now-lastTapTime<300&&lastTapSide===side){dash=side;shake=Math.max(shake,.08);soundEffect(380,.14,'triangle',.1);}lastTapTime=now;lastTapSide=side;},{passive:false});
function releasePointer(e){if(activePointer===e.pointerId){activePointer=null;steer=0;}}canvas.addEventListener('pointerup',releasePointer);canvas.addEventListener('pointercancel',releasePointer);canvas.addEventListener('lostpointercapture',()=>{activePointer=null;steer=0;});
window.addEventListener('keydown',e=>{if(e.key==='ArrowLeft'||e.key==='a')steer=-1;if(e.key==='ArrowRight'||e.key==='d')steer=1;if(e.key===' '&&running){dash=steer||1;}});window.addEventListener('keyup',e=>{if(['ArrowLeft','ArrowRight','a','d'].includes(e.key))steer=0;});
function spawnParticles(x,y,z,color,count=14){for(let i=0;i<count;i++){const mesh=new THREE.Mesh(new THREE.IcosahedronGeometry(.08+Math.random()*.14,0),new THREE.MeshBasicMaterial({color,transparent:true}));mesh.position.set(x,y,z);scene.add(mesh);particles.push({mesh,vx:(Math.random()-.5)*8,vy:1+Math.random()*7,vz:(Math.random()-.5)*8,life:.45+Math.random()*.65});}}
let invulnerable=0, cameraTargetX=0, zone=-1;
function refreshZone(){const next=Math.floor(worldDistance/1050);if(next===zone)return;zone=next;const colors=next%3===0?['#e98d91','#f1a083','#f7a58d']:next%3===1?['#425a86','#3a496f','#596d9c']:['#252a62','#27275b','#473875'];scene.fog.color.set(colors[0]);scene.background.set(colors[1]);skyDome.material.color.set(colors[2]);sunLight.color.set(next%3===0?'#fff1cf':'#a9c8ff');sunLight.intensity=next%3===0?2.2:1.55;glowLight.color.set(next%3===0?'#ff9c9b':next%3===1?'#70b5ff':'#fa62df');document.querySelector('#distance').textContent=(next%3===0?'SUNSET COUNTY':next%3===1?'GOLDEN HIGHWAY':'NEON CITY')+' · '+(worldDistance/1000).toFixed(1)+' KM';}
function recycleProp(e){e.z-=segmentCount*segLength;const kind=Math.floor(worldDistance/1050)%3;if(e.kind==='shoulder')return;if(kind===1){e.kind=Math.random()<.58?'lamp':Math.random()<.55?'fence':'tree';}else if(kind===2){e.kind=Math.random()<.68?'neon':'lamp';}else{const r=Math.random();e.kind=r<.61?'tree':r<.77?'fence':r<.9?'flower':'barn';}e.side=Math.random()<.5?-1:1;e.offset=8+Math.random()*17;e.scale=.65+Math.random()*.8;buildProp(e);}
function update(dt){elapsed+=dt;beat=Math.max(0,beat-dt*2.7);const speedBoost=1+Math.min(worldDistance/7000,.23);if(running){speed=Math.min(34,speed+.22*dt);worldDistance+=speed*dt;score+=dt*(8+speed*.32);playerX+=steer*dt*(8.2+speed*.12);if(dash){playerX+=dash*dt*14;dash*=Math.max(0,1-dt*4.4);if(Math.abs(dash)<.06)dash=0;}playerX=THREE.MathUtils.clamp(playerX,-7.2,7.2);invulnerable=Math.max(0,invulnerable-dt);}
 const roadCenter=pathX(worldDistance);player.position.set(roadCenter+playerX,0,playerZ);player.rotation.y=pathAngle(worldDistance);playerCar.userData.body.rotation.z=THREE.MathUtils.damp(playerCar.userData.body.rotation.z,-steer*.11+dash*.11,5,dt);playerCar.userData.body.position.y=.035*Math.sin(elapsed*8*speed/20);playerCar.visible=!(invulnerable>0&&Math.floor(elapsed*18)%2===0);
 roadSegments.forEach(o=>{o.z+=running?speed*dt:0;if(o.z>18)o.z-=segmentCount*segLength;const c=pathX(worldDistance-o.z);o.group.position.set(c,0,o.z);o.group.rotation.y=pathAngle(worldDistance-o.z);const city=Math.floor(worldDistance/1050)%3===2;o.group.children.forEach(ch=>{if(ch.material===mats.road)ch.material=city?mats.asphalt:mats.road;});});
 objects.forEach(e=>{e.z+=running?speed*dt:0;if(e.z>18)recycleProp(e);const center=pathX(worldDistance-e.z);if(e.kind==='shoulder'){e.mesh.position.set(center+(e.mesh.position.x<center? -20:20),-.39,e.z);if(e.z>12)e.z-=segmentCount*5;}
 else{e.group.position.set(center+e.side*(roadWidth/2+e.offset),-.15,e.z);e.group.rotation.y=pathAngle(worldDistance-e.z);if(e.kind==='neon')e.group.rotation.y+=e.side*.2;}});
 traffic.forEach(t=>{if(running)t.z+=(speed-t.speed)*dt;if(t.z>14){t.z=-115-Math.random()*65;t.x=[-4.1,0,4.1][Math.floor(Math.random()*3)];t.hit=false;t.knock=0;t.mesh.visible=true;}const center=pathX(worldDistance-t.z);t.mesh.position.set(center+t.x+t.dx,.02,t.z);t.mesh.rotation.y=pathAngle(worldDistance-t.z);t.mesh.rotation.z=THREE.MathUtils.damp(t.mesh.rotation.z,t.knock,5,dt);t.dx*=Math.max(0,1-dt*.72);t.knock*=Math.max(0,1-dt*2.4);
 const lateral=Math.abs((center+t.x)-(roadCenter+playerX));if(running&&invulnerable<=0&&!t.hit&&Math.abs(t.z)<2.9&&lateral<1.6){t.hit=true;invulnerable=1.05;contacts++;updateContacts();shake=.29;speed=Math.max(16,speed-1.6);t.dx=(playerX-t.x)>=0?6:-6;t.knock=t.dx>0?-.22:.22;score+=80;spawnParticles(player.position.x,.9,.2,'#ffd47d',18);soundEffect(155,.32,'sawtooth',.19);if(contacts>=3)finish();}else if(running&&t.hit&&Math.abs(t.z)>4.4)t.hit=false;
 if(running&&dash&&Math.abs(t.z)<11&&Math.abs((center+t.x)-(roadCenter+playerX))<3.6&&!t.hit){t.dx+=dash*12;t.knock=-dash*.34;score+=25;spawnParticles(t.mesh.position.x,.8,t.z,'#7de4df',5);t.hit=true;setTimeout(()=>t.hit=false,750);}
 });
 particles.forEach((p,i)=>{p.life-=dt;p.mesh.position.x+=p.vx*dt;p.mesh.position.y+=p.vy*dt;p.mesh.position.z+=p.vz*dt;p.vy-=11*dt;p.mesh.material.opacity=Math.max(0,p.life);if(p.life<=0){scene.remove(p.mesh);particles.splice(i,1);}});
